mapper.select:
SELECT id, movie_id AS movieId, code, date FROM hello_movie WHERE movie_id IN
#{movieId}
AND deleted = 0

SELECT movie_staff.movie_id AS movieId, staff.id AS id, staff.name AS name, staff.cover AS cover FROM movie_staff LEFT JOIN staff ON movie_staff.staff_id = staff.id LEFT JOIN position ON movie_staff.position_id = position.id WHERE movie_staff.deleted = 0 AND position.name = '監督' AND movie_staff.movie_id IN
#{movieId}
ORDER BY movie_staff.movie_id, movie_staff.staff_id

SELECT DISTINCT movie_show_time.movie_id AS movie_id, movie_show_time.spec_ids AS spec_ids, movie_show_time.reservation_params_json->>'reservation_url' AS reservation_url, -- 爬虫透传的售票/座位状态：on_sale / few / sold_out / pre_sale / sale_ended / closed / unknown -- 用于 app 端在没有自家 seat 表数据时也能给到准确的座位状态图标。 movie_show_time.crawl_raw_json->>'status' AS sale_status, cinema.id AS cinema_id, cinema.name AS cinema_name, cinema.full_address AS cinema_address, cinema.tel AS cinema_tel, cinema.latitude AS cinema_latitude, cinema.longitude AS cinema_longitude,
(fav.id IS NOT NULL) AS is_favorite, movie_show_time.id AS id, movie_show_time.start_time AS start_time, movie_show_time.end_time AS end_time, theater_hall.id AS theater_hall_id, theater_hall.name AS theater_hall_name, movie_show_time.re_release_id AS re_release_id, re_release.version_info AS re_release_version_info, ( SELECT string_agg(cs.name, '、' ORDER BY array_position(movie_show_time.spec_ids, cs.id)) FROM cinema_spec cs WHERE cs.id = ANY(movie_show_time.spec_ids) AND cs.deleted = 0 ) AS spec_name, movie_show_time.dimension_type, movie_show_time.subtitle_id, -- 字幕语言名称（按 subtitle_id 原顺序「、」拼接），用于列表卡片直接展示 ( SELECT string_agg(l.name, '、' ORDER BY array_position(movie_show_time.subtitle_id, l.id)) FROM language l WHERE movie_show_time.subtitle_id IS NOT NULL AND l.id = ANY(movie_show_time.subtitle_id) AND l.deleted = 0 ) AS subtitle_names, movie_show_time.show_time_tag_id, movie_show_time.movie_version_id, -- 原版 / 配音版：importer 写入 movie_show_time.dub_version（1=オリジナル版, 2=吹き替え版）。 -- 旧数据若仍走 movie_version.version_code，则作为 fallback。 COALESCE(movie_show_time.dub_version, movie_version.version_code) AS version_code, ( SELECT COUNT(seat.id) FROM seat WHERE seat.theater_hall_id = theater_hall.id AND seat.deleted = 0 AND seat.show = TRUE ) AS total_seats, ( SELECT COUNT(select_seat.id) FROM select_seat LEFT JOIN movie_order ON movie_order.id = select_seat.movie_order_id WHERE select_seat.movie_show_time_id = movie_show_time.id AND select_seat.deleted = 0 AND movie_order.order_state = 2 ) AS selected_seats,
( 6371000 * acos( cos(radians(#{query.latitude})) * cos(radians(cinema.latitude)) * cos(radians(cinema.longitude) - radians(#{query.longitude})) + sin(radians(#{query.latitude})) * sin(radians(cinema.latitude)) ) ) AS distance
NULL AS distance
FROM movie_show_time LEFT JOIN cinema ON movie_show_time.cinema_id = cinema."id" LEFT JOIN theater_hall ON movie_show_time.theater_hall_id = theater_hall.id LEFT JOIN movie_version ON movie_version.id = movie_show_time.movie_version_id AND movie_version.deleted = 0 LEFT JOIN re_release ON re_release.id = movie_show_time.re_release_id AND re_release.deleted = 0 LEFT JOIN user_favorite_cinema fav ON fav.cinema_id = cinema.id AND fav.deleted = 0 AND fav.user_id = #{query.userId} WHERE movie_show_time.deleted = 0 AND movie_show_time.status = #{showTimeState} AND movie_show_time.movie_id = #{query.movieId}
AND movie_show_time.re_release_id = #{query.reReleaseId}
AND movie_show_time.re_release_id IS NULL
AND movie_show_time.start_time::timestamp >= now() AND cinema.deleted = 0
AND cinema.region_id = #{query.regionId}
AND cinema.prefecture_id = #{query.prefectureId}
AND cinema.city_id = #{query.cityId}
AND cinema.brand_id IN #{bid}
AND #{query.subtitleId} = ANY(movie_show_time.subtitle_id)
AND movie_show_time.spec_ids && ARRAY[ #{id} ]
AND #{query.showTimeTagId} = ANY(movie_show_time.show_time_tag_id)
AND movie_show_time.dimension_type = #{query.dimensionType}
AND COALESCE(movie_show_time.dub_version, movie_version.version_code) = #{query.versionCode}
AND ( cinema.name LIKE '%' || #{query.keyword} || '%' OR cinema.full_address LIKE '%' || #{query.keyword} || '%' )
AND TO_CHAR(movie_show_time.start_time::timestamp, 'HH24:MI') >= #{query.startTimeFrom}
AND TO_CHAR(movie_show_time.start_time::timestamp, 'HH24:MI') <= #{query.startTimeTo}
AND cinema.latitude IS NOT NULL AND cinema.longitude IS NOT NULL AND ( 6371000 * acos( cos(radians(#{query.latitude})) * cos(radians(cinema.latitude)) * cos(radians(cinema.longitude) - radians(#{query.longitude})) + sin(radians(#{query.latitude})) * sin(radians(cinema.latitude)) ) ) <= #{query.radius}
ORDER BY
is_favorite DESC, distance ASC

SELECT DISTINCT sid
FROM movie_show_time mst, unnest(mst.subtitle_id) AS sid
WHERE mst.deleted = 0
  AND mst.status = #{showTimeState}
  AND mst.movie_id = #{query.movieId}


          AND mst.re_release_id = #{query.reReleaseId}


          AND mst.re_release_id IS NULL


  AND mst.start_time::timestamp >= now()

SELECT DISTINCT tid
FROM movie_show_time mst, unnest(mst.show_time_tag_id) AS tid
WHERE mst.deleted = 0
  AND mst.status = #{showTimeState}
  AND mst.movie_id = #{query.movieId}


          AND mst.re_release_id = #{query.reReleaseId}


          AND mst.re_release_id IS NULL


  AND mst.start_time::timestamp >= now()
